const body = $input.first().json.body ?? $input.first().json;
const message = body.message || '';
const history = body.history || [];

const messages = [
  {
    role: 'system',
    content: `You are an AI assistant for RudraAI, an n8n automation agency based in Hyderabad, India. You help visitors understand our services, pricing, and how AI automation can save their business time and money.

Services we offer:
- n8n workflow automation (from $50 for 1 automation)
- AI agent development
- Lead qualification automations
- CRM integrations
- Email sequence automation
- Client onboarding automation

Pricing:
- 1 automation: $50
- 3 automations: $100
- 5 automations: $200
- 5+ automations: Contact us

Always be helpful, concise, and guide users to book a free audit call at /booking. Do not make up information.`
  },
  ...history,
  { role: 'user', content: message }
];

return [{ json: { messages, message } }];

const openRouterResult = $('OpenRouter (Primary)').first();
const ollamaResult = $('Ollama (Fallback)').first();

let reply = 'Sorry, I am having trouble connecting. Please email hello@rudraai.io.';

try {
  const orData = openRouterResult.json;
  if (orData && orData.choices && orData.choices[0]) {
    reply = orData.choices[0].message.content;
  } else {
    const olData = ollamaResult.json;
    if (olData && olData.message) {
      reply = olData.message.content;
    }
  }
} catch (e) {}

return [{ json: { reply } }];

// Ollama is PRIMARY — OpenRouter is optional fallback
const ollamaResult = $('Ollama (Primary)').first();
const openRouterResult = $('OpenRouter (Optional Fallback)').first();

let reply = 'Sorry, I am having trouble connecting. Please email hello@rudraai.io.';

try {
  const olData = ollamaResult.json;
  if (olData && olData.message && olData.message.content) {
    reply = olData.message.content;
